--
-- Table structure for table `maritime_course`
--

DROP TABLE IF EXISTS `maritime_course`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `maritime_course` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '课程ID',
  `name` varchar(100) NOT NULL COMMENT '课程名称',
  `certificate_type` varchar(50) NOT NULL COMMENT '证书类型（如：STCW、精通急救）',
  `cover_image` varchar(500) DEFAULT NULL COMMENT '封面图片URL',
  `description` text COMMENT '课程详情（富文本HTML）',
  `enrollment_condition_text` text COMMENT '报名条件说明文本（仅前端展示，线下验证）',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '状态（0下架 1上架）',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT '排序权重（越大越靠前）',
  `creator` varchar(64) NOT NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) NOT NULL DEFAULT '' COMMENT '更新者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除（0正常 1删除）',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  PRIMARY KEY (`id`),
  KEY `idx_certificate_type` (`certificate_type`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='课程模板表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `maritime_course`
--

LOCK TABLES `maritime_course` WRITE;
/*!40000 ALTER TABLE `maritime_course` DISABLE KEYS */;
INSERT INTO `maritime_course` (`id`, `name`, `certificate_type`, `cover_image`, `description`, `enrollment_condition_text`, `status`, `sort_order`, `creator`, `updater`, `create_time`, `update_time`, `deleted`, `tenant_id`) VALUES (1,'二管轮 / 三管轮航区扩大','适任培训','http://127.0.0.1:48080/admin-api/infra/file/4/get/20261022/2guanlun3gl.jpg','<h3>课程介绍</h3><p>面向已经取得相应适任证书，希望进一步扩大本人适任证书航区的船员。不是零基础培训，也不同于三管轮晋升。</p><h3>适合人群</h3><p>已持有相应二管轮或三管轮适任证书，因工作或职业发展需要进行航区扩大的船员。</p><h3>培训包含</h3><p>• 二管轮航区扩大</p><p>• 三管轮航区扩大</p><h3>专业课程</h3><p>• 按航区扩大培训要求开展规定的轮机专业理论及相关培训</p><p>• 具体科目按当期教学计划执行</p><p><br></p><p><br></p><p><br></p>','根据本人现有适任证书、航区及海上服务资历等情况进行资格审核，建议先审核、后确认报名。\n\n',1,100,'seed','seed','2026-07-05 08:40:52','2026-07-05 08:40:52',0,1),(2,'一年制三副培训','适任培训','http://127.0.0.1:48080/admin-api/infra/file/4/get/20261022/sanguang-2.jpg','<h3>课程介绍</h3><p>面向具有大专及以上学历，希望进入海船甲板部并向三副岗位发展的人员。课程包含合格证、专业课程及三副相关适任培训。</p><h3>适合人群</h3><p>大专及以上学历；希望进入海船甲板部工作并向三副、二副、大副、船长方向发展的人员。</p><h3>培训包含</h3><p>• Z01 基本安全</p><p>• Z07 保安意识</p><p>• Z08 负有指定保安职责</p><p>• Z02 精通救生艇筏和救助艇</p><p>• Z04 高级消防</p><p>• Z05 精通急救</p><h3>专业课程</h3><p>• 三管轮相关适任培训</p><p>• 轮机专业理论</p><p>• 轮机设备相关课程</p><p>• 轮机值班及实操</p><p><br></p>','具有大专及以上学历；\n其他报名条件以资料审核结果为准。\n',1,90,'seed','seed','2026-07-05 08:40:52','2026-07-05 08:40:52',0,1),(3,'值班水手培训','适任培训','http://127.0.0.1:48080/admin-api/infra/file/4/get/20261022/sanfu-2.jpg','<h3>课程简介</h3><p>值班水手是海船甲板部支持级船员，主要参与航行值班、系离泊、甲板设备维护等工作。课程面向准备从水手岗位进入海员行业的人员。</p><h3>适合人群</h3><p>尚未取得值班水手适任资格，希望进入海船甲板部工作，并继续向三副、二副、大副、船长方向发展的人员。</p><h3>培训内容</h3><p>• Z01 基本安全</p><p>• Z07 保安意识</p><p>• Z08 负有指定保安职责</p><p>• Z02不包含，可加报840元</p><h3>专业课程</h3><p>• 值班水手适任培训</p><p>• 水手值班</p><p>• 水手工艺</p><p>• 水手英语</p><p>• 相关实操训练</p>','身体健康: 无影响船上工作的心脏病、高血压等疾病；\n无色盲、色弱；\n最终以资料审核为准。\n',1,84,'1','1','2026-08-13 01:56:41','2026-08-13 01:56:41',0,1),(4,'值班机工培训','适任培训','http://127.0.0.1:48080/admin-api/infra/file/4/get/20261022/zhibanjig.jpg','<h3>课程简介</h3><p>值班机工是海船轮机部支持级船员，主要协助轮机员完成机舱值班、设备日常操作维护等工作。</p><h3>适合人群</h3><p>尚未取得值班机工适任资格，希望进入海船轮机部工作，并继续向三管轮、二管轮、大管轮、轮机长发展的人员。</p><h3>培训内容</h3><p>• Z01 基本安全</p><p>• Z07 保安意识</p><p>• Z08 负有指定保安职责</p><p>• Z02不包含，可加报840元</p><h3>专业课程</h3><p>• 值班机工适任培训</p><p>• 机工值班</p><p>• 机工业务</p><p>• 轮机基础知识</p><p>• 轮机英语</p><p>• 相关实操训练</p><p><br></p>','身体健康；无影响船上工作的心脏病、高血压等疾病；\n无色盲、色弱；\n最终以资料审核为准。\n',1,82,'1','1','2026-08-13 01:56:41','2026-08-13 01:56:41',0,1),(5,'三副晋升培训','适任培训','http://127.0.0.1:48080/admin-api/infra/file/4/get/20261022/sanfu-2.jpg','<h3>课程简介</h3><p>三副属于海船甲板部操作级船员。本课程面向具有相应海上服务资历、准备参加三副适任培训和考试的船员。</p><h3>适合人群</h3><p>已经从事海船甲板部相关工作，具有相应海上服务资历，准备由支持级向操作级发展的船员。</p><h3>培训包含</h3><p>• Z02 精通救生艇筏和救助艇</p><p>• Z04 高级消防</p><p>• Z05 精通急救</p><h3>专业课程</h3><p>• 三副适任培训</p><p>• 航海专业理论</p><p>• 航海值班相关课程</p><p>• 相关实操训练</p><p><br></p>','海上资历不少于18个月，实习资历不计入；\n涉及甲类无限航区还需满足相应资历要求，建议先审核证书及海上服务资历。\n',1,88,'1','1','2026-08-13 01:56:41','2026-08-13 01:56:41',0,1),(6,'三管轮晋升培训','适任培训','http://127.0.0.1:48080/admin-api/infra/file/4/get/20261022/sanguang-3.jpg','<h3>课程简介</h3><p>三管轮属于海船轮机部操作级船员。本课程面向具有相应海上服务资历、准备参加三管轮适任培训和考试的船员。</p><h3>适合人群</h3><p>已经从事海船轮机部相关工作，具有相应海上服务资历，准备参加三管轮适任培训和考试的船员。</p><h3>培训包含</h3><p>• Z02 精通救生艇筏和救助艇</p><p>• Z04 高级消防</p><p>• Z05 精通急救</p><h3>专业课程</h3><p>• 三管轮适任培训</p><p>• 轮机专业理论</p><p>• 轮机设备管理</p><p>• 轮机值班业务</p><p>• 相关实操训练</p>','海上资历不少于18个月，实习资历不计入；\n涉及甲类无限航区还需满足相应资历要求，建议先审核证书及海上服务资历。\n',1,86,'1','1','2026-08-13 01:56:41','2026-08-13 01:56:41',0,1),(7,'GMDSS 通用操作员培训','适任培训','http://127.0.0.1:48080/admin-api/infra/file/4/get/20261022/gmdss2.jpg','<h3>课程简介</h3><p>GMDSS（全球海上遇险与安全系统）通用操作员证书（GOC）是船舶通信岗位的必备适任证书，驾驶员在船操作 GMDSS 设备必须持证。课程依托 GMDSS 模拟机房开展，还原真实海上通信场景，系统训练遇险、紧急与安全通信的规范操作。</p><h3>适用人群</h3><ul><li>有GMDSS培训需求，或因适任培训、证书及船上岗位需要参加相关培训的人员；</li><li>一年制三副学习期间也可按需选择；</li></ul><h3>培训包含</h3><p>• GMDSS专项培训</p><h3>专业课程</h3><p>• 海上无线电通信理论</p><p>• GMDSS设备使用</p><p>• 遇险、紧急及安全通信</p><p>• 日常通信操作</p><p>• 设备实操训练</p>','1. 完成航海类相关专业规定学历教育或相应职业培训；\n2. 符合海船船员健康检查标准；\n3. 已持有基本安全培训等相应合格证；\n4. 具体报名条件以现场审核为准。',1,80,'1','1','2026-08-13 01:56:41','2026-08-13 01:56:41',0,1),(8,'基本安全更新（Z01）','合格证','http://127.0.0.1:48080/admin-api/infra/file/4/get/20261022/hegezheng.png','<h3>课程简介</h3><p>面向已经持有相应海船船员培训合格证，因证书到期或换证需要参加知识更新培训的船员。属于证书更新，不是初次培训。</p>','已经持有相关合格证、需要进行知识更新并符合相应更新培训条件的船员。\n不确定更新项目时可先提交现有证书核对。\n',1,70,'1','1','2026-08-13 01:56:41','2026-08-13 01:56:41',0,1),(9,'精通艇筏和救助艇培训（Z02）','合格证','http://127.0.0.1:48080/admin-api/infra/file/4/get/20261022/qiantingpeixun.png','<h3>课程简介</h3><p>面向已经持有相应海船船员培训合格证，因证书到期或换证需要参加知识更新培训的船员。属于证书更新，不是初次培训。</p>','已经持有相关合格证、需要进行知识更新并符合相应更新培训条件的船员。\n不确定更新项目时可先提交现有证书核对。\n',1,65,'1','1','2026-08-13 01:56:41','2026-08-13 01:56:41',0,1),(10,'高级消防培训更新（Z04）','合格证','http://127.0.0.1:48080/admin-api/infra/file/4/get/20261022/xiaofang.jpg','<h3>课程简介</h3><p>面向已经持有相应海船船员培训合格证，因证书到期或换证需要参加知识更新培训的船员。属于证书更新，不是初次培训。</p>','已经持有相关合格证、需要进行知识更新并符合相应更新培训条件的船员。\n不确定更新项目时可先提交现有证书核对。\n',1,60,'1','1','2026-08-13 01:56:41','2026-08-13 01:56:41',0,1),(11,'一年制三管轮培训','适任培训','http://127.0.0.1:48080/admin-api/infra/file/4/get/20261022/sanfu.jpg','<h3>课程介绍</h3><p>面向具有大专及以上学历，希望进入海船轮机部并向三管轮岗位发展的人员。课程包含合格证、轮机专业课程及相关适任培训。</p><h3>适合人群</h3><p>大专及以上学历；希望进入海船轮机部工作，并向三管轮、二管轮、大管轮、轮机长方向发展的人员。</p><h3>培训包含</h3><p>• Z01 基本安全</p><p>• Z07 保安意识</p><p>• Z08 负有指定保安职责</p><p>• Z02 精通救生艇筏和救助艇</p><p>• Z04 高级消防</p><p>• Z05 精通急救</p><h3>专业课程</h3><p>• 三管轮相关适任培训</p><p>• 轮机专业理论</p><p>• 轮机设备相关课程</p><p>• 轮机值班及实操</p><p><br></p>','具有大专及以上学历；\n其他报名条件以资料审核结果为准。\n',1,101,'1','1','2026-10-22 15:53:42','2026-10-22 15:53:42',0,1);
/*!40000 ALTER TABLE `maritime_course` ENABLE KEYS */;
