,8,'2026-10-SH-001','基本安全课程-10月',6,NULL,'2026-12-10','2026-12-15','2026-12-07',25,7,'OPEN',NULL,'seed','1','2026-09-18 03:06:08','2026-10-28 03:15:17',0,1),(14,3,'2026-10-QD-002','值班水手-10月班',15,'张船长','2026-12-18','2027-01-01','2026-12-15',20,5,'OPEN','<p><br></p>','seed','1','2026-09-18 03:06:08','2026-10-27 07:13:09',0,1);
