INSERT INTO `maritime_session_venue` (`id`, `session_id`, `campus_name`, `province`, `city`, `district`, `address`, `latitude`, `longitude`, `contact_phone`, `campus_intro`, `accommodation_intro`, `classroom_intro`, `creator`, `updater`, `create_time`, `update_time`, `deleted`, `tenant_id`) VALUES (1,14,'武汉航海职业技术学院','','','','武汉市武昌区喻家湖148号',30.5838069,114.3348930,'13667228630','<p><span style=\"color: rgba(0, 0, 0, 0.9); background-color: rgb(255, 255, 255); font-size: 16px; font-family: -apple-system, system-ui, &quot;Segoe UI&quot;, system-ui, Roboto, &quot;Noto Sans&quot;, Ubuntu, Cantarell, &quot;Helvetica Neue&quot;, sans-serif, Arial, &quot;PingFang SC&quot;, &quot;Source Han Sans SC&quot;, &quot;Microsoft YaHei UI&quot;, &quot;Microsoft YaHei&quot;, &quot;Noto Sans CJK SC&quot;;\">武汉航海职业技术学院隶属招商局集团旗下长航集团，创建于1955年，是首批\"新机制、新模式\"试点高职院校。学校立足航海特色，开设航海技术、轮机工程技术等专业15个，轮机、港口航运等3个专业获中央财政重点支持。依托长航集团产业链，实行\"现代学徒制\"，设招商南油、中远海等订单班，实现\"入校即就业\"。毕业生就业率近五年保持90%以上，就业单位遍布全球航运名企，成为特色鲜明的产教融合型高职院校。</span></p><p><img src=\"http://127.0.0.1:48080/admin-api/infra/file/4/get/editor-default-image/20260923/school.jpg\" alt=\"image\" data-href=\"http://127.0.0.1:48080/admin-api/infra/file/4/get/editor-default-image/20260923/school.jpg\" width=\"\" height=\"\" style=\"\"/></p>','<p>学院学生宿舍环境整洁舒适，配套设施完善，配有空调、热水、独立卫浴等设施，实行规范化管理，生活便利。校园内食堂、超市、运动场所一应俱全，为学生营造了安全、温馨的居住生活环境。<br><img src=\"http://127.0.0.1:48080/admin-api/infra/file/4/get/editor-default-image/20260923/Weixin%20Image_20260919205007_16_30.png\" alt=\"image\" data-href=\"http://127.0.0.1:48080/admin-api/infra/file/4/get/editor-default-image/20260923/Weixin Image_20260919205007_16_30.png\" width=\"\" height=\"\" style=\"\"/></p>','<p>学院建有船舶操纵模拟器等21个校内实验室和10多个校外实训基地，配备先进设备1000多台（套），航海技术实验室为省级重点建设实验室，教学条件国内一流。<br><img src=\"http://127.0.0.1:48080/admin-api/infra/file/4/get/editor-default-image/20260923/Weixin%20Image_20260919203727_12_30.png\" alt=\"image\" data-href=\"http://127.0.0.1:48080/admin-api/infra/file/4/get/editor-default-im